import{z as i,x as d,o as l,c as A,q as s,j as n,D as t,d as e,s as o,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"故障检测器","description":"","frontmatter":{"title":"故障检测器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/failure-detectors.md","filePath":"cs/failure-detectors.md","lastUpdated":1791413859000}'),c={name:"cs/failure-detectors.md"};function D(p,a,m,C,h,u){const r=d("Mermaid");return l(),A("div",null,[a[2]||(a[2]=s('<h1 id="故障检测器" tabindex="-1">故障检测器 <a class="header-anchor" href="#故障检测器" aria-label="Permalink to &quot;故障检测器&quot;">​</a></h1><div class="epigraph"><p>异步里不能可靠地知道谁死了。把「怀疑」做成预言机：完备与准确分档，共识的最小档是 $\\Diamond\\mathcal{P}$。</p><footer>—— 据 Chandra and Toueg, Unreliable Failure Detectors for Reliable Distributed Systems, JACM 1996；Chandra, Hadzilacos and Toueg, 1996 整理</footer></div><p>上一课<a href="/cs/chandy-lamport">快照</a>能切一致状态，切不出「这个进程还会不会再发消息」。上一课之前的<a href="/cs/sync-async-model">异步模型</a>里，超时不是原语。缺口是<strong>把怀疑从协议里抽出来</strong>：检测器输出「我怀疑 \\(p\\)」，协议只读这张名单。本课不重做崩溃定义。后课租约是检测器在实现里的一种带期限的形式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>崩溃停进程终将停止发消息；异步调度可以让活进程任意久不出现。任何基于超时的本地判断都可能错。Chandra–Toueg 不消除错误，而是给检测器<strong>性质</strong>：</p><ul><li>完备（completeness）：真故障终被所有正确进程怀疑。</li><li>准确（accuracy）：永不（或最终永不、或至少有一个正确进程永不）误伤正确进程。</li></ul><p>最强 \\(\\mathcal{P}\\)（Perfect）：强完备 + 强准确。最常用 \\(\\Diamond\\mathcal{P}\\)（eventually perfect）：终有一时刻之后，怀疑名单恰好是故障集。\\(\\Diamond\\mathcal{S}\\) 更弱，却已够异步崩溃共识（配多数派）。</p><p><span class="marginnote">CHT 1996 证明 \\(\\Diamond\\mathcal{S}\\) 是无初始值共识的最弱检测器。本课记结论，不搬归约证明。</span><span class="marginnote">术语翻译：完备是「别漏报」——真死的必须进怀疑名单；准确是「别误报」——活着的别被拉黑。异步网络里二者没法同时保证，所以只能退一步要「最终」版本（\\(\\Diamond\\) 读作「终将」）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现上几乎都是心跳 + 自适应超时（φ accrual 等）：部分同步下终将成为 \\(\\Diamond\\mathcal{P}\\)。算法分层：共识模块只调用 <code>suspect(p)</code>，不内嵌 RTT。这样同一套 Paxos 可以换检测器实现。</p>',10)),(l(),n(B,null,{default:t(()=>[o(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20HB%5B%22%E5%BF%83%E8%B7%B3%22%5D%20--%3E%20FD%5B%22%E6%A3%80%E6%B5%8B%E5%99%A8%22%5D%0A%20%20FD%20--%3E%20SUS%5B%22%E6%80%80%E7%96%91%E5%90%8D%E5%8D%95%22%5D%0A%20%20SUS%20--%3E%20CONS%5B%22%E5%85%B1%E8%AF%86%20%2F%20%E9%80%89%E4%B8%BE%20%E5%90%8E%E8%AF%BE%22%5D%0A%20%20SYNC%5B%22%E9%83%A8%E5%88%86%E5%90%8C%E6%AD%A5%22%5D%20-.-%3E%20FD%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[e("错误怀疑的代价：把活领导者踢掉，活性抖动，安全性仍应成立——这把"),E("a",{href:"/cs/sync-async-model"},"时间模型"),e("里「安全异步、活靠同步」说成了接口。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"强准确在真实网络几乎得不到：偶发长延迟就会误杀。所以工程检测器是 \\(\\Diamond\\) 类。心跳间隔与超时是运维旋钮，不是规格：调小则快但误伤多，调大则故障切换慢。租约下一课把「准确直到到期」做成短时的强准确窗口。",-1)),(l(),n(B,null,{default:t(()=>[o(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROOT%5B%22%E6%A3%80%E6%B5%8B%E5%99%A8%E6%A1%A3%E4%BD%8D%E6%80%8E%E4%B9%88%E5%88%86%EF%BC%9F%22%5D%20--%3E%20DIM1%7B%22%E6%80%80%E7%96%91%E5%90%8D%E5%8D%95%E6%9C%80%E7%BB%88%E4%BC%9A%E6%94%B6%E6%95%9B%E5%90%97%EF%BC%9F%22%7D%0A%20%20DIM1%20--%3E%7C%22%E4%BC%9A%E6%94%B6%E6%95%9B%22%7C%20DIM2%7B%22%E6%94%B6%E6%95%9B%E5%90%8E%E8%BF%98%E8%AF%AF%E4%BC%A4%E6%AD%A3%E7%A1%AE%E8%BF%9B%E7%A8%8B%E5%90%97%EF%BC%9F%22%7D%0A%20%20DIM2%20--%3E%7C%22%E4%B8%8D%E8%AF%AF%E4%BC%A4%E4%BB%BB%E4%BD%95%E4%BA%BA%22%7C%20P%5B%22P%20%2F%20%E2%97%87P%EF%BC%9A%E5%90%8D%E5%8D%95%E6%81%B0%E5%A5%BD%E7%AD%89%E4%BA%8E%E6%95%85%E9%9A%9C%E9%9B%86%22%5D%0A%20%20DIM2%20--%3E%7C%22%E5%8F%AF%E8%83%BD%E8%AF%AF%E4%BC%A4%EF%BC%8C%E4%BD%86%E8%87%B3%E5%B0%91%E6%94%BE%E8%BF%87%E4%B8%80%E4%B8%AA%E6%AD%A3%E7%A1%AE%E8%BF%9B%E7%A8%8B%22%7C%20DS%5B%22%E2%97%87S%EF%BC%9A%E6%9C%80%E5%BC%B1%E6%A1%A3%EF%BC%8C%E9%85%8D%E5%A4%9A%E6%95%B0%E6%B4%BE%E5%B7%B2%E5%A4%9F%E5%85%B1%E8%AF%86%22%5D%0A%20%20DIM1%20--%3E%7C%22%E4%B8%8D%E4%BF%9D%E8%AF%81%E6%94%B6%E6%95%9B%22%7C%20W%5B%22%E6%9B%B4%E5%BC%B1%E7%9A%84%E6%A1%A3%EF%BC%8C%E5%B7%A5%E7%A8%8B%E4%B8%8A%E5%B0%91%E7%94%A8%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">数字实例：心跳每秒一发、超时 5 秒——网络抖动 4 秒，平安无事；抖 6 秒，对方明明活着却被拉黑。调超时就是在「多久能发现真故障」与「多久误报一次」之间定价，不存在两全的数值。</span></p><p>漏发故障下，检测器看到的是「不说话」，与崩溃不可分。拜占庭下「心跳还在」不表示协议被遵守，检测器抽象要另做——后课 PBFT 用法定人数与视图更换，不是 Chandra–Toueg 原版。</p><p>本课不把 Kubernetes liveness probe 当 \\(\\mathcal{P}\\)：探针失败只是本地重启策略，没有分布式完备性证明。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证最弱检测器，不写 φ 的公式。不把监控告警当成检测器输出。后课默认：异步共识读 \\(\\Diamond\\mathcal{S}\\) 或更强；实现用心跳逼近 \\(\\Diamond\\mathcal{P}\\)；误怀疑只许破坏活性。快照不是检测手段。</p><p>没有这层抽象，超时会偷偷写进安全证明，FLP 的异步前提就被偷换。<span class="marginnote">常见误区：初学者容易把 Kubernetes liveness 探针失败当成「机器死了的证明」；它只是触发本地重启的策略条件，没有任何分布式完备性——被重启的实例可能只是慢，未必真死了。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>检测器把不可靠怀疑做成带完备/准确档的预言机。</li><li>\\(\\Diamond\\mathcal{S}\\) 已够崩溃共识；\\(\\mathcal{P}\\) 在真实网络不可得。</li><li>心跳实现依赖部分同步；安全仍按异步证。</li><li>出处：Chandra and Toueg, JACM 1996；Chandra, Hadzilacos and Toueg。</li></ul>',8))])}const T=i(c,[["render",D]]);export{f as __pageData,T as default};
